$var = RandomVariableName(); Context()->variables->are($var => 'Real'); $x = random(1, 9); $a = list_random(-9..-2, 2..9); $b = random(2, 3, 1); $expression = Formula("($a $var)^$b")->reduce; $answer = $expression->eval($var => $x); $answer = Real($answer); Context("LimitedNumeric"); $answer = Real($answer);
############################# # Exercise Group Introduction #############################
BEGIN_PGML Evaluate the expression for the given value of the variable.
END_PGML
###### # Body ######
BEGIN_PGML [`[$expression]`] for [`[$var]=[$x]\text{.}`]
[_]{$answer}{15}
END_PGML
